import React from "react";
export const useFeedbackAlertState = () => {
    const [apiAlertActions, setApiAlertActions] = React.useState([]);
    const [alerts, setAlerts] = React.useState([]);
    const [alertsQueue, setAlertsQueue] = React.useState([]);
    const [alertsAnimation, setAlertsAnimation] = React.useState([]);
    const removedAlertId = React.useRef(null);
    return {
        alerts,
        setAlerts,
        alertsQueue,
        setAlertsQueue,
        alertsAnimation,
        setAlertsAnimation,
        removedAlertId,
        apiAlertActions,
        setApiAlertActions
    };
};
